// reconnect and when the page becomes visible again (PLAN 6.3).
function refetch() {
  return fetch('/healthz', {cache: 'no-store'})
    .then(function (r) { return r.ok; }).catch(function () { return false; });
}
function connect() {
  var ws = new WebSocket('wss://' + location.host + '/ws');
  ws.onopen = function () {
    WS_OPENS += 1;
