    }

    /// Milliseconds of a duration, for the `after N ms` log lines.
    nonisolated static func milliseconds(_ d: Duration) -> Int {
        Int(d.components.seconds) * 1000 + Int(d.components.attoseconds / 1_000_000_000_000_000)
    }

