            Row(label: "Relay", value: relaySummary),
            Row(label: "Relay restarts", value: "\(counters.socksRelayRestarts)"),
            Row(label: "Relay probes", value: "\(counters.socksRelayProbes) (\(counters.socksRelayProbesFailed) found it dead)"),
