  var handler = handlers && handlers.kiroBlocked;
  var ATTR = 'data-latchkey-blocked';
  var LABEL = 'Image not loaded. Tap to open in Safari.';
  function post(m) { try { if (handler) { handler.postMessage(m); } } catch (e) {} }

  function absolute(u) {
    try {
