setTimeout(function () {
  var m = document.querySelector('img[data-latchkey-blocked]');
  if (m) { m.click(); }
  try {
    if (handler()) {
      window.webkit.messageHandlers.kiroBlocked.postMessage({event: 'open', url: AWAY + '/f6/img.png'});
    }

